+    static class CountedComparator implements Comparator<Item> {
+        int comparisons;
+
+        public int compare(Item x, Item y) {
+            comparisons++;
+            return x.compareTo(y);
+        }
+    }
+
+    static class CountedAddPriorityQueue<E> extends PriorityQueue<E> {
+        int adds;
+
+        public boolean add(E e) {
+            adds++;
+            return super.add(e);
+        }
+    }
